<?php
if(!defined('ABSPATH'))exit;
const MC_VERSION='2.0.2';
const MC_PUBLIC_ORIGIN='https://marinoceramictile.com';
add_action('after_setup_theme',function(){foreach(['title-tag','post-thumbnails','responsive-embeds','editor-styles','wp-block-styles','custom-logo']as$s)add_theme_support($s);add_editor_style(['assets/app.css','assets/blocks.css']);});
add_action('enqueue_block_assets',function(){if(is_admin())wp_enqueue_style('mc-editor-fonts','https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,300;0,400;0,500;0,600;1,300;1,400&family=Inter:wght@300;400;500;600;700&display=swap',[],null);});
add_action('wp_enqueue_scripts',function(){wp_enqueue_style('mc-fonts','https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,300;0,400;0,500;0,600;1,300;1,400&family=Inter:wght@300;400;500;600;700&display=swap',[],null);wp_enqueue_style('mc-app',get_theme_file_uri('/assets/app.css'),['mc-fonts'],MC_VERSION);wp_enqueue_style('mc-blocks',get_theme_file_uri('/assets/blocks.css'),['mc-app'],MC_VERSION);wp_enqueue_script('mc-runtime',get_theme_file_uri('/assets/runtime.js'),[],MC_VERSION,true);});
add_action('init',function(){
 add_rewrite_rule('^blog/([^/]+)/?$','index.php?name=$matches[1]','top');
 wp_register_script('mc-editor',get_theme_file_uri('/assets/editor.js'),['wp-blocks','wp-element','wp-block-editor','wp-components','wp-data','wp-plugins','wp-edit-post'],MC_VERSION,true);
 register_block_type('marino/form',['api_version'=>3,'editor_script'=>'mc-editor','attributes'=>['action'=>['type'=>'string','default'=>'/contact/'],'method'=>['type'=>'string','default'=>'get'],'accessKey'=>['type'=>'string','default'=>''],'subject'=>['type'=>'string','default'=>''],'fromName'=>['type'=>'string','default'=>''],'submitLabel'=>['type'=>'string','default'=>'Send message'],'submitClass'=>['type'=>'string','default'=>''],'className'=>['type'=>'string','default'=>'']],'supports'=>['html'=>false]]);
 register_block_type('marino/field',['api_version'=>3,'editor_script'=>'mc-editor','attributes'=>['label'=>['type'=>'string','default'=>'Email'],'name'=>['type'=>'string','default'=>'email'],'type'=>['type'=>'string','default'=>'email'],'placeholder'=>['type'=>'string','default'=>''],'required'=>['type'=>'boolean','default'=>false],'rows'=>['type'=>'number','default'=>6],'className'=>['type'=>'string','default'=>''],'inputClass'=>['type'=>'string','default'=>''],'labelClass'=>['type'=>'string','default'=>'eyebrow']],'supports'=>['html'=>false]]);
 register_block_type('marino/post-label',['api_version'=>3,'editor_script'=>'mc-editor','attributes'=>['field'=>['type'=>'string','default'=>'category'],'prefix'=>['type'=>'string','default'=>''],'className'=>['type'=>'string','default'=>'']],'uses_context'=>['postId'],'render_callback'=>function($a,$content,$block){$id=(int)($block->context['postId']??get_the_ID());$field=$a['field']??'category';$v=$field==='reading-time'?max(1,(int)ceil(str_word_count(wp_strip_all_tags(get_post_field('post_content',$id)))/220)).' min read':get_post_meta($id,$field==='author'?'_mc_author':'_mc_category',true);return'<p '.get_block_wrapper_attributes().'>'.esc_html(($a['prefix']??'').($v?:'Marino Ceramic Tile')).'</p>';}]);
 foreach(['post','page']as$type)foreach(['_mc_author','_mc_category','rank_math_title','rank_math_description','rank_math_focus_keyword','rank_math_canonical_url','rank_math_facebook_image','rank_math_twitter_image']as$key)register_post_meta($type,$key,['type'=>'string','single'=>true,'show_in_rest'=>true,'sanitize_callback'=>'sanitize_text_field','auth_callback'=>fn($allowed,$key,$id)=>current_user_can('edit_post',$id)]);
});
add_filter('post_link',fn($url,$post)=>$post->post_type==='post'?home_url('/blog/'.$post->post_name.'/'):$url,10,2);
function mc_post_faq(int $id):array{$items=[];$walk=function($blocks)use(&$walk,&$items){foreach($blocks as$b){if($b['blockName']==='core/details'&&preg_match('#<summary[^>]*>(.*?)</summary>#s',$b['innerHTML'],$m)){$answer='';foreach($b['innerBlocks']as$child)$answer.=wp_strip_all_tags(render_block($child)).' ';$items[]=[wp_strip_all_tags($m[1]),trim($answer)];}$walk($b['innerBlocks']);}};$walk(parse_blocks(get_post_field('post_content',$id)));return$items;}
require __DIR__.'/inc/seo.php';
add_filter('query_loop_block_query_vars',function($q,$b){$id=(int)($b->context['queryId']??0);if(is_singular('post')&&$id===702)$q['post__not_in']=array_unique(array_merge($q['post__not_in']??[],[get_queried_object_id()]));return$q;},10,2);
add_action('template_redirect',function(){if(!is_page('blog'))return;$raw=$_GET['query-700-page']??null;$invalid=$raw!==null&&(!is_scalar($raw)||!ctype_digit((string)$raw)||(int)$raw<1);$maximum=max(1,(int)ceil(wp_count_posts('post')->publish/24));if($invalid||(int)$raw>$maximum){global$wp_query;$wp_query->set_404();status_header(404);nocache_headers();remove_action('template_redirect','redirect_canonical');}},1);
add_action('after_switch_theme',function(){flush_rewrite_rules(false);});
